import { useState, useCallback } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

const startOfDay = (date: Date) => {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
};

const isSameDay = (a: Date | null, b: Date) =>
  !!a && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();

interface ReportDatePickerProps {
  onChange?: (date: Date | null) => void;
}

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date | null>(null);

  const setDate = useCallback(
    (date: Date | null) => {
      setValue(date);
      onChange?.(date);
    },
    [onChange]
  );

  const today = startOfDay(new Date());
  const yesterday = startOfDay(new Date(Date.now() - 24 * 60 * 60 * 1000));
  const weekAgo = startOfDay(new Date(Date.now() - 7 * 24 * 60 * 60 * 1000));

  const quickOptions: { label: string; date: Date }[] = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: yesterday },
    { label: 'Неделя назад', date: weekAgo },
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12, width: 'fit-content' }}>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
        {quickOptions.map((option) => (
          <JxButton
            key={option.label}
            type="button"
            size="sm"
            variant={isSameDay(value, option.date) ? 'primary' : 'outline'}
            onClick={() => setDate(option.date)}
          >
            {option.label}
          </JxButton>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={value} onValueChange={setDate} />
    </div>
  );
}

